SELECT it.id, it.flight_id AS flightId, it.model_name AS modelName, it.status, it.total_detections AS totalDetections, it.start_time AS startTime, it.end_time AS endTime FROM inference_tasks it LEFT JOIN flights f ON it.flight_id = f.id
AND (f.user_id = #{userId} OR it.user_id = #{userId})
AND it.flight_id = #{flightId}
ORDER BY it.start_time DESC LIMIT #{offset}, #{pageSize}

SELECT COUNT(*) FROM inference_tasks it LEFT JOIN flights f ON it.flight_id = f.id
AND (f.user_id = #{userId} OR it.user_id = #{userId})
AND it.flight_id = #{flightId}
